<x-layouts.app :title="$customer->name"><div class="mb-7 flex items-end justify-between"><div><p class="eyebrow">Customer profile</p><h1 class="page-title">{{ $customer->name }}</h1><p class="page-copy">{{ $customer->phone }} · {{ $customer->nic?:'No NIC recorded' }}</p></div><a class="secondary-button" href="{{ route('customers.edit',$customer) }}">Edit</a></div>
