<section class="panel mt-6"><div class="panel-header"><h2 class="section-title">Phones and financing</h2></div><div class="overflow-x-auto"><table class="data-table"><thead><tr><th>Device</th><th>Status</th><th>Selling</th><th>Paid</th><th>Remaining</th><th>Next due</th></tr></thead><tbody>@foreach($customer->devices as $d)@php($next=$d->financing?->installments->whereNotIn('status',['paid','waived'])->sortBy('due_date')->first())<tr><td><a class="font-bold text-indigo-600" href="{{ route('devices.show',$d) }}">{{ $d->brand }} {{ $d->model }}</a></td><td>{{ $d->status }} / {{ $d->lock_status }}</td><td>{{ number_format($d->selling_price,2) }}</td><td>{{ number_format($d->financing?->total_paid??0,2) }}</td><td>{{ number_format($d->financing?->remaining_balance??0,2) }}</td><td>{{ $next?->due_date?->format('d M Y')??'Completed' }}</td></tr>@endforeach</tbody></table></div></section>
